// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 a) internal {
        a = bound(a, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance > a);
        try c.addToBalance{value: a}() {} catch { return; }
        uint256 beforeRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeRecorded = __r; } catch { return; }
        uint beforeContractEth = address(c).balance;
        uint beforeTestEth = address(this).balance;
        bool reverted;
        try c.addToBalance{value: 0}() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted && c.getBalance(address(this)) == beforeRecorded && address(c).balance == beforeContractEth && address(this).balance == beforeTestEth);
    }

    function testFuzz_run(uint256 a) public {
        _run(a);
    }

    receive() external payable {}
}
